import { ESortOrder, ETableSearchParams } from 'shared/typings';

export const getDefaultSortOrder = (searchParams: URLSearchParams, columnName: string) => {
	const ordering = searchParams.get(ETableSearchParams.ORDERING);
	const defaultSortOrder = ordering?.startsWith('-') ? ESortOrder.DESC : ESortOrder.ASC;
	return ordering?.endsWith(columnName) ? defaultSortOrder : undefined;
};
